   978  int hts_parse_format(htsFormat *format, const char *str) {
   979      char fmt[8];
   980      const char *cp = scan_keyword(str, ',', fmt, sizeof fmt);
   981
   982      format->version.minor = 0; // unknown
   983      format->version.major = 0; // unknown
   984
   985      if (strcmp(fmt, "sam") == 0) {
   986          format->category          = sequence_data;
   987          format->format            = sam;
   988          format->compression       = no_compression;;
   989          format->compression_level = 0;
   990      } else if (strcmp(fmt, "sam.gz") == 0) {
   991          format->category          = sequence_data;
   992          format->format            = sam;
   993          format->compression       = bgzf;
   994          format->compression_level = -1;
   995      } else if (strcmp(fmt, "bam") == 0) {
   996          format->category          = sequence_data;
   997          format->format            = bam;
   998          format->compression       = bgzf;
   999          format->compression_level = -1;
  1000      } else if (strcmp(fmt, "cram") == 0) {
  1001          format->category          = sequence_data;
  1002          format->format            = cram;
  1003          format->compression       = custom;
  1004          format->compression_level = -1;
  1005      } else if (strcmp(fmt, "vcf") == 0) {
  1006          format->category          = variant_data;
  1007          format->format            = vcf;
  1008          format->compression       = no_compression;;
  1009          format->compression_level = 0;
  1010      } else if (strcmp(fmt, "bcf") == 0) {
  1011          format->category          = variant_data;
  1012          format->format            = bcf;
  1013          format->compression       = bgzf;
  1014          format->compression_level = -1;
  1015      } else {
  1016          return -1;
  1017      }
  1018
  1019      return hts_parse_opt_list(format, cp);
  1020  }
