  1052                                   hFILE **hfile_ptr, htsFile *fp) {
  1053      hFILE *hfile1 = *hfile_ptr;
  1054      hFILE *hfile2 = NULL;
  1055      char fn_buf[512], *fn2 = fn_buf;
  1056      const char *prefix = "crypt4gh:";
  1057      size_t fn2_len = strlen(prefix) + strlen(fn) + 1;
  1058      int ret = -1;
  1059
  1060      if (fn2_len > sizeof(fn_buf)) {
  1061          fn2 = malloc(fn2_len);
  1062          if (!fn2) return -1;
  1063      }
  1064
  1065      // Reopen fn using the crypt4gh plug-in (if available)
  1066      snprintf(fn2, fn2_len, "%s%s", prefix, fn);
  1067      hfile2 = hopen(fn2, mode, "parent", hfile1, NULL);
  1068      if (hfile2) {
  1069          // Replace original hfile with the new one.  The original is now
  1070          // enclosed within hfile2
  1071          *hfile_ptr = hfile2;
  1072          ret = 0;
  1073      }
  1074
  1075      if (fn2 != fn_buf)
  1076          free(fn2);
  1077      return ret;
  1078  }
