  1080  htsFile *hts_hopen(hFILE *hfile, const char *fn, const char *mode)
  1081  {
  1082      hFILE *hfile_orig = hfile;
  1083      htsFile *fp = (htsFile*)calloc(1, sizeof(htsFile));
  1084      char simple_mode[101], *cp, *opts;
  1085      simple_mode[100] = '\0';
  1086
  1087      if (fp == NULL) goto error;
  1088
  1089      fp->fn = strdup(fn);
  1090      fp->is_be = ed_is_big();
