  1092      // Split mode into simple_mode,opts strings
  1093      if ((cp = strchr(mode, ','))) {
  1094          strncpy(simple_mode, mode, cp-mode <= 100 ? cp-mode : 100);
  1095          simple_mode[cp-mode] = '\0';
  1096          opts = cp+1;
  1097      } else {
  1098          strncpy(simple_mode, mode, 100);
  1099          opts = NULL;
  1100      }
  1101
  1102      if (strchr(simple_mode, 'r')) {
  1103          const int max_loops = 5; // Should be plenty
  1104          int loops = 0;
  1105          if (hts_detect_format(hfile, &fp->format) < 0) goto error;
  1106
  1107          // Deal with formats that re-direct an underlying file via a plug-in.
  1108          // Loops as we may have crypt4gh served via htsget, or
  1109          // crypt4gh-in-crypt4gh.
  1110          while (fp->format.format == htsget ||
  1111                 fp->format.format == hts_crypt4gh_format) {
  1112              // Ensure we don't get stuck in an endless redirect loop
  1113              if (++loops > max_loops) {
  1114                  errno = ELOOP;
  1115                  goto error;
  1116              }
  1117
  1118              if (fp->format.format == htsget) {
  1119                  hFILE *hfile2 = hopen_htsget_redirect(hfile, simple_mode);
  1120                  if (hfile2 == NULL) goto error;
  1121
  1122                  hfile = hfile2;
  1123              }
