  1134          htsFormat *fmt = &fp->format;
  1135          fp->is_write = 1;
  1136
  1137          if (strchr(simple_mode, 'b')) fmt->format = binary_format;
  1138          else if (strchr(simple_mode, 'c')) fmt->format = cram;
  1139          else fmt->format = text_format;
  1140
  1141          if (strchr(simple_mode, 'z')) fmt->compression = bgzf;
  1142          else if (strchr(simple_mode, 'g')) fmt->compression = gzip;
  1143          else if (strchr(simple_mode, 'u')) fmt->compression = no_compression;
  1144          else {
  1145              // No compression mode specified, set to the default for the format
  1146              switch (fmt->format) {
  1147              case binary_format: fmt->compression = bgzf; break;
  1148              case cram: fmt->compression = custom; break;
  1149              case text_format: fmt->compression = no_compression; break;
  1150              default: abort();
  1151              }
  1152          }
  1153
  1154          // Fill in category (if determinable; e.g. 'b' could be BAM or BCF)
  1155          fmt->category = format_category(fmt->format);
  1156
  1157          fmt->version.major = fmt->version.minor = -1;
  1158          fmt->compression_level = -1;
  1159          fmt->specific = NULL;
  1160      }
  1161      else { errno = EINVAL; goto error; }
  1162
  1163      switch (fp->format.format) {
  1164      case binary_format:
  1165      case bam:
  1166      case bcf:
  1167          fp->fp.bgzf = bgzf_hopen(hfile, simple_mode);
  1168          if (fp->fp.bgzf == NULL) goto error;
  1169          fp->is_bin = fp->is_bgzf = 1;
  1170          break;
  1171
  1172      case cram:
  1173          fp->fp.cram = cram_dopen(hfile, fn, simple_mode);
  1174          if (fp->fp.cram == NULL) goto error;
  1175          if (!fp->is_write)
  1176              cram_set_option(fp->fp.cram, CRAM_OPT_DECODE_MD, -1); // auto
  1177          fp->is_cram = 1;
  1178          break;
  1179
  1180      case empty_format:
  1181      case text_format:
  1182      case bed:
  1183      case fasta_format:
  1184      case fastq_format:
  1185      case sam:
  1186      case vcf:
  1187          if (fp->format.compression != no_compression) {
  1188              fp->fp.bgzf = bgzf_hopen(hfile, simple_mode);
  1189              if (fp->fp.bgzf == NULL) goto error;
  1190              fp->is_bgzf = 1;
  1191          }
  1192          else
  1193              fp->fp.hfile = hfile;
  1194          break;
  1195
  1196      default:
  1197          errno = EFTYPE;
  1198          goto error;
  1199      }
  1200
  1201      if (opts)
  1202          hts_process_opts(fp, opts);
  1203
  1204      // If redirecting, close the original hFILE now (pedantically we would
  1205      // instead close it in hts_close(), but this a simplifying optimisation)
  1206      if (hfile != hfile_orig) hclose_abruptly(hfile_orig);
  1207
  1208      return fp;
  1209
  1210  error:
  1211      hts_log_error("Failed to open file %s", fn);
  1212
  1213      // If redirecting, close the failed redirection hFILE that we have opened
  1214      if (hfile != hfile_orig) hclose_abruptly(hfile);
  1215
  1216      if (fp) {
  1217          free(fp->fn);
  1218          free(fp->fn_aux);
  1219          free(fp);
  1220      }
  1221      return NULL;
  1222  }
